CREATE TABLE provider_applications (id BIGINT AUTO_INCREMENT PRIMARY KEY, account_id BIGINT NOT NULL, status VARCHAR(15) NOT NULL CHECK(status IN ('PENDIENTE','ACEPTADA','RECHAZADA')), person_type VARCHAR(10) NOT NULL CHECK(person_type IN ('NATURAL','JURIDICA')), nit VARCHAR(15) NOT NULL, verification_digit INT NOT NULL CHECK(verification_digit BETWEEN 0 AND 9), legal_name VARCHAR(200) NOT NULL, trade_name VARCHAR(160), legal_representative VARCHAR(160), representative_document VARCHAR(40), phone VARCHAR(20) NOT NULL, address VARCHAR(200) NOT NULL, city VARCHAR(100) NOT NULL, submitted_at DATETIME(6) NOT NULL, decided_by BIGINT, decided_at DATETIME(6), rejection_reason VARCHAR(500), notified_at DATETIME(6), CHECK((status = 'PENDIENTE') = (decided_at IS NULL)), FOREIGN KEY(account_id) REFERENCES users(id), FOREIGN KEY(decided_by) REFERENCES users(id));
CREATE INDEX idx_provider_applications_status ON provider_applications(status, submitted_at);
CREATE INDEX idx_provider_applications_account ON provider_applications(account_id, submitted_at);
CREATE INDEX idx_provider_applications_nit ON provider_applications(nit, status);
